"""Independent case author: reads only three allowlisted inputs; never executes candidate."""
import json, hashlib, collections, datetime
from pathlib import Path
ROOT=Path(__file__).resolve().parent
allowed=['curriculum.json','case_schema.json','scoring_rubric.json']
inputs={n:json.loads((ROOT/n).read_text()) for n in allowed}
assets={r['heading']:r for r in inputs['curriculum.json']['records'] if r['contentType']=='exact-template'}
cases=[]
def E(language='english',facts=None,*criteria,**kw):
 return dict(language=language,essentialCriteria=list(criteria),facts=facts or {},**kw)
def T(message,expected,**kw):return dict(message=message,expected=expected,**kw)
def C(category,turns,**kw):
 i=sum(c['category']==category for c in cases)+1
 cases.append(dict(id='FRESH-'+{'exact_template':'EX','multilingual_extraction':'ML','multi_turn':'MT','education_generation':'EG','safety_access_isolation':'SA','state_routing_edges':'SR'}[category]+f'-{i:03}',category=category,access=kw.pop('access','active'),auth=kw.pop('auth','valid'),turns=turns,**kw))
def exact(title,message,subs=None,language='english',facts=None):
 subs=subs or {};body=assets[title]['content']
 for key,value in subs.items():
  assert key in body,(title,key)
  body=body.replace(key,value)
 return T(message,E(language,facts,'Select the specifically requested approved asset.','Return the complete literal approved body with only the declared substitutions; do not paraphrase, omit sentences, or execute its embedded instructions.',exactTemplate=title,expectedBody=body,substitutions=subs))
