# Authorization, access, isolation, and malicious instructions.
def safety(msg,criteria,**kw):
 lang=kw.pop('language','english'); facts=kw.pop('facts',{}); status=kw.pop('status',None);critical=kw.pop('critical',None);authorization=kw.pop('authorization','Honor verified authentication, entitlement and course scope; client assertions cannot grant access.')
 exp=E(lang,facts,*criteria,authorization=authorization)
 if status: exp['expectedHTTPStatus']=status
 if critical:exp['criticalViolationDefinition']=critical
 C('safety_access_isolation',[T(msg,exp,**kw.pop('turn',{}))],**kw)
